insert into public.imoveis (id, data) values ('63135', '{"areaTotal": 203.86, "atualizadoEm": "2026-11-17T22:40:00.000Z", "bairro": "Jardim Vale do Sol", "caracteristicas": ["Esquina", "Terreno plano", "Asfalto", "Rede de água e esgoto", "Iluminação pública"], "categoria": "Terreno", "cidade": "Cornélio Procópio", "codigo": "63135", "criadoEm": "2023-09-01T12:00:00Z", "descricao": "Terreno de esquina no Jardim Vale do Sol, próximo ao Jardim Primavera, à quadra esportiva, salão de festas e mercado.\n\nJá conta com toda a infraestrutura: rede de água, esgoto, asfalto, meio-fio, iluminação pública e rede de energia. Pronto para construir, totalmente plano, para uso residencial ou comercial.\n\nLote nº 8, 12,50 m x 16,12 m: 203,86 m².", "destaque": false, "finalidade": "venda", "fotos": ["/fotos/63135_0.webp", "/fotos/63135_1.webp", "/fotos/63135_2.webp"], "preco": 150000, "status": "disponivel", "titulo": "Terreno de esquina no Jardim Vale do Sol", "uf": "PR"}'::jsonb) on conflict (id) do update set data = excluded.data;
