insert into public.imoveis (id, data) values ('89473', '{"areaTotal": 272, "atualizadoEm": "2026-11-17T22:40:00.000Z", "bairro": "Rancho do Sossego", "banheiros": 2, "caracteristicas": ["Vista para o rio", "Condomínio fechado", "Churrasqueira", "Edícula", "Despensa", "Armário na cozinha", "Armário no quarto", "Box no banheiro", "Área de serviço", "Jardim", "Quintal", "Murado", "Arborização"], "categoria": "Casa de condomínio", "cidade": "Leópolis", "codigo": "89473", "criadoEm": "2024-10-03T12:00:00Z", "descricao": "Seu novo lar à beira do rio. Casa em condomínio fechado (Rancho do Sossego) com 2 quartos, 2 banheiros, sala ampla, cozinha integrada com edícula, despensa e garagem para 2 carros.\n\nTudo isso em um cenário deslumbrante, com a tranquilidade e a segurança que você merece. Agende sua visita.", "destaque": true, "finalidade": "venda", "fotos": ["/fotos/89473_0.webp", "/fotos/89473_1.webp", "/fotos/89473_2.webp", "/fotos/89473_3.webp"], "preco": 350000, "quartos": 2, "status": "disponivel", "titulo": "Casa à beira do rio no Rancho do Sossego", "uf": "PR", "vagas": 2}'::jsonb) on conflict (id) do update set data = excluded.data;
insert into public.imoveis (id, data) values ('99327', '{"areaConstruida": 260, "areaTotal": 240, "atualizadoEm": "2026-11-17T22:40:00.000Z", "bairro": "Centro", "categoria": "Comercial", "cidade": "Cornélio Procópio", "codigo": "99327", "criadoEm": "2025-02-21T11:00:00Z", "descricao": "Oportunidade única para o seu novo negócio ou projeto. Barracão espaçoso e casa inclusa, tudo em um só lugar. Ideal para quem busca espaço, conforto e versatilidade.\n\nLocalização privilegiada, potencial de crescimento e ótimo custo-benefício. Entre em contato e agende uma visita.", "destaque": true, "finalidade": "venda", "fotos": ["/fotos/99327_0.webp", "/fotos/99327_1.webp", "/fotos/99327_2.webp", "/fotos/99327_3.webp"], "preco": 480000, "status": "disponivel", "titulo": "Barracão espaçoso com casa inclusa", "uf": "PR"}'::jsonb) on conflict (id) do update set data = excluded.data;
